const supersedeAnaesthesiaAssessment = `-- name: SupersedeAnaesthesiaAssessment :exec
UPDATE anaesthesia.assessment
SET superseded_by = $1, superseded_at = $2
WHERE tenant_id = $3 AND assessment_id = $4
  AND superseded_by IS NULL
`

type SupersedeAnaesthesiaAssessmentParams struct {
	SupersededBy pgtype.UUID
	SupersededAt pgtype.Timestamptz
	TenantID     uuid.UUID
	AssessmentID uuid.UUID
}

// Supersession is a separate statement because the one-current index forbids
// two live assessments for a case: the old row has to point at the new one
// before the new one may exist, and the forward reference is deferrable so the
// pair can be written in either order inside a transaction.
func (q *Queries) SupersedeAnaesthesiaAssessment(ctx context.Context, arg SupersedeAnaesthesiaAssessmentParams) error {
	_, err := q.db.Exec(ctx, supersedeAnaesthesiaAssessment,
		arg.SupersededBy,
		arg.SupersededAt,
		arg.TenantID,
		arg.AssessmentID,
	)
	return err
}

